<script setup>
import {computed,watch,ref} from 'vue';
import {Head,Link,useForm,router} from '@inertiajs/vue3';
import AdminLayout from '../../Components/AdminLayout.vue';
import {states,money} from '../../labels';
const props=defineProps({kind:String,record:Object,products:Array,services:Array,branches:Array,destinations:Array,segments:Array,inventories:Array,transitions:Array,capabilities:Object,assignees:Array,receipt:Object});
const titles={stock:'Movimentar stock',transferencias:props.record?'Transferência '+props.record.reference:'Nova transferência',pedidos:props.record?'Pedido '+props.record.public_id:'Novo pedido',contactos:'Contacto'};
const stock=useForm({product_id:'',branch_id:'',quantity:'',expected_quantity:'0',operation_id:crypto.randomUUID(),reason:'',type:'adjustment'});
const current=computed(()=>props.inventories?.find(i=>i.product_id===stock.product_id&&i.branch_id===stock.branch_id));
watch(current,i=>{stock.expected_quantity=i?.quantity||'0';stock.quantity='';stock.operation_id=crypto.randomUUID();limits.minimum_quantity=i?.minimum_quantity||'0';limits.maximum_quantity=i?.maximum_quantity||'';});
const limits=useForm({minimum_quantity:'0',maximum_quantity:''});
const transfer=useForm({segment_id:'',source_branch_id:'',destination_branch_id:'',notes:'',items:[{product_id:'',quantity:1}]});
const order=useForm({segment_id:'',branch_id:'',customer:{name:'',phone:'',email:'',company:''},items:[{product_id:'',service_id:'',quantity:1}],notes:'',idempotency_key:crypto.randomUUID()});
const context=computed(()=>props.kind==='transferencias'?transfer:order);
const selectedProducts=computed(()=>props.products?.filter(p=>p.segment_id===context.value.segment_id)||[]);
const selectedServices=computed(()=>props.services?.filter(p=>p.segment_id===order.segment_id)||[]);
function locations(list,segment){return (list||[]).filter(b=>!segment||b.segments?.some(s=>s.id===segment));}
watch(()=>context.value.segment_id,()=>{context.value.items=[props.kind==='transferencias'?{product_id:'',quantity:1}:{product_id:'',service_id:'',quantity:1}];context.value.branch_id='';context.value.source_branch_id='';context.value.destination_branch_id='';});
const transition=useForm({status:'',reason:''});
const details=useForm({notes:props.record?.notes||'',assigned_to:props.record?.assigned_to||'',status:props.record?.status||'new'});
const action=useForm({});
const editingDraft=ref(false);
const draft=useForm({notes:props.record?.notes||'',items:(props.record?.stock_transfer_items||[]).map(i=>({product_id:i.product_id,quantity:i.quantity}))});
function submitStock(){stock.post('/admin/stock/ajustes',{preserveScroll:true,onSuccess:()=>{stock.operation_id=crypto.randomUUID();stock.expected_quantity=current.value?.quantity||'0';stock.quantity='';stock.reason='';}});}
function submitOrder(){order.transform(d=>({...d,items:d.items.map(i=>({quantity:i.quantity,...(i.service_id?{service_id:i.service_id}:{product_id:i.product_id})}))})).post('/admin/pedidos');}
</script>
<template><AdminLayout><Head :title="titles[kind]"/><div class="page-heading"><div><span class="eyebrow">Operações</span><h1>{{titles[kind]}}</h1><p v-if="record" class="badge">{{states[record.status]||record.status}}</p></div><Link :href="'/admin/'+kind" class="button outline small">← Voltar</Link></div>
<template v-if="kind==='stock'"><form class="panel admin-form" @submit.prevent="submitStock"><div class="form-grid"><div class="field"><label for="stock-product">Produto</label><select id="stock-product" v-model="stock.product_id" required><option value="">Selecionar…</option><option v-for="p in products" :key="p.id" :value="p.id">{{p.name}}</option></select></div><div class="field"><label for="stock-branch">Filial</label><select id="stock-branch" v-model="stock.branch_id" required><option value="">Selecionar…</option><option v-for="b in locations(branches,products.find(p=>p.id===stock.product_id)?.segment_id)" :key="b.id" :value="b.id">{{b.name}}</option></select></div><div class="field"><label for="stock-type">Operação</label><select id="stock-type" v-model="stock.type"><option value="adjustment">Contagem / ajuste do saldo</option><option value="entry">Entrada</option><option value="exit">Saída</option><option value="return">Devolução</option></select></div><div class="field"><label for="stock-quantity">{{stock.type==='adjustment'?'Saldo contado':'Quantidade'}} · saldo atual: {{current?.quantity||'0'}}</label><input id="stock-quantity" type="number" min="0" step="0.001" v-model="stock.quantity" required></div><div class="field full"><label for="stock-reason">Motivo</label><textarea id="stock-reason" v-model="stock.reason" required minlength="3" maxlength="1000"/></div></div><button class="button" :disabled="stock.processing">Registar movimento</button></form><form v-if="current" class="panel admin-form" @submit.prevent="limits.transform(d=>({...d,maximum_quantity:d.maximum_quantity===''?null:d.maximum_quantity})).patch('/admin/stock/'+current.id+'/limites')"><h2>Limites de stock</h2><div class="form-grid"><div class="field"><label for="minimum">Mínimo</label><input id="minimum" type="number" min="0" step="0.001" v-model="limits.minimum_quantity" required></div><div class="field"><label for="maximum">Máximo (opcional)</label><input id="maximum" type="number" :min="limits.minimum_quantity" step="0.001" v-model="limits.maximum_quantity"></div></div><button class="button" :disabled="limits.processing">Guardar limites</button></form></template>
<form v-else-if="!record" class="panel admin-form" @submit.prevent="kind==='transferencias'?transfer.post('/admin/transferencias'):submitOrder()"><div class="form-grid"><div class="field"><label for="op-segment">Segmento</label><select id="op-segment" v-model="context.segment_id" required><option value="">Selecionar…</option><option v-for="s in segments" :key="s.id" :value="s.id">{{s.name}}</option></select></div><div class="field"><label for="op-branch">{{kind==='transferencias'?'Origem':'Filial'}}</label><select v-if="kind==='transferencias'" id="op-branch" v-model="transfer.source_branch_id" required><option value="">Selecionar…</option><option v-for="b in locations(branches,context.segment_id)" :key="b.id" :value="b.id">{{b.name}}</option></select><select v-else id="op-branch" v-model="order.branch_id" required><option value="">Selecionar…</option><option v-for="b in locations(branches,context.segment_id)" :key="b.id" :value="b.id">{{b.name}}</option></select></div><div v-if="kind==='transferencias'" class="field"><label for="destination">Destino</label><select id="destination" v-model="transfer.destination_branch_id" required><option value="">Selecionar…</option><option v-for="b in locations(destinations,transfer.segment_id).filter(b=>b.id!==transfer.source_branch_id)" :key="b.id" :value="b.id">{{b.name}}</option></select></div></div><template v-if="kind==='pedidos'"><h2>Cliente</h2><div class="form-grid"><div v-for="(label,key) in {name:'Nome',phone:'Telefone',email:'Email',company:'Empresa'}" :key="key" class="field"><label :for="'customer-'+key">{{label}}</label><input :id="'customer-'+key" v-model="order.customer[key]" :type="key==='email'?'email':'text'" :required="['name','phone'].includes(key)"></div></div></template><h2>Itens</h2><div v-for="(item,index) in context.items" :key="index" class="form-grid item-row"><div class="field"><label :for="'item-'+index">Produto</label><select :id="'item-'+index" v-model="item.product_id" :required="!item.service_id" @change="item.service_id=''"><option value="">Selecionar…</option><option v-for="p in selectedProducts" :key="p.id" :value="p.id">{{p.name}}</option></select></div><div v-if="kind==='pedidos'" class="field"><label :for="'service-'+index">Ou serviço</label><select :id="'service-'+index" v-model="item.service_id" @change="item.product_id=''"><option value="">Selecionar…</option><option v-for="s in selectedServices" :key="s.id" :value="s.id">{{s.name}}</option></select></div><div class="field"><label :for="'qty-'+index">Quantidade</label><input :id="'qty-'+index" type="number" min="0.001" max="9999" step="0.001" v-model="item.quantity" required></div><button v-if="context.items.length>1" class="text-link" type="button" @click="context.items.splice(index,1)">Remover item</button></div><button type="button" class="button outline small" @click="context.items.push({product_id:'',service_id:'',quantity:1})">+ Adicionar item</button><div class="field"><label for="op-notes">Notas</label><textarea id="op-notes" v-model="context.notes" maxlength="1000"/></div><button class="button" :disabled="context.processing">{{kind==='transferencias'?'Criar rascunho':'Criar pedido'}}</button></form>
<template v-else><section class="panel admin-form"><template v-if="kind==='transferencias'"><h2>{{record.source_branch?.name}} → {{record.destination_branch?.name}}</h2><p>{{record.notes}}</p><div class="table-scroll"><table><thead><tr><th>Produto</th><th>Quantidade</th></tr></thead><tbody><tr v-for="i in record.stock_transfer_items" :key="i.id"><td>{{i.product?.name}}</td><td>{{i.quantity}}</td></tr></tbody></table></div><div class="button-row"><button v-if="record.status==='draft'&&capabilities?.dispatch" class="button" :disabled="action.processing" @click="action.post('/admin/transferencias/'+record.id+'/dispatch')">Expedir</button><button v-if="record.status==='dispatched'&&capabilities?.receive" class="button" :disabled="action.processing" @click="action.post('/admin/transferencias/'+record.id+'/receive')">Confirmar receção</button><button v-if="record.status==='draft'&&capabilities?.cancel" class="button outline" :disabled="action.processing" @click="action.post('/admin/transferencias/'+record.id+'/cancel')">Cancelar rascunho</button></div><button v-if="record.status==='draft'&&capabilities?.cancel" class="button outline small" @click="editingDraft=!editingDraft">{{editingDraft?'Fechar edição':'Editar rascunho'}}</button><form v-if="editingDraft&&record.status==='draft'" @submit.prevent="draft.patch('/admin/transferencias/'+record.id,{onSuccess:()=>editingDraft=false})"><h3>Itens do rascunho</h3><div v-for="(item,index) in draft.items" :key="index" class="form-grid"><div class="field"><label :for="'draft-product-'+index">Produto</label><select :id="'draft-product-'+index" v-model="item.product_id" required><option v-for="p in products.filter(p=>p.segment_id===record.segment_id)" :key="p.id" :value="p.id">{{p.name}}</option></select></div><div class="field"><label :for="'draft-qty-'+index">Quantidade</label><input :id="'draft-qty-'+index" v-model="item.quantity" type="number" step="0.001" min="0.001" required></div><button v-if="draft.items.length>1" type="button" @click="draft.items.splice(index,1)">Remover</button></div><button type="button" class="button outline small" @click="draft.items.push({product_id:'',quantity:1})">Adicionar item</button><div class="field"><label for="draft-notes">Notas</label><textarea id="draft-notes" v-model="draft.notes"/></div><button class="button" :disabled="draft.processing">Guardar rascunho</button></form><p v-if="record.status==='dispatched'" class="notice">Stock debitado na origem. A receção credita o destino.</p></template>
<template v-else-if="kind==='pedidos'"><h2>{{record.customer_snapshot?.name}}</h2><p>{{record.customer_snapshot?.phone}} · {{record.customer_snapshot?.email}}</p><p>Filial: {{record.branch?.name}}</p><div class="table-scroll"><table><thead><tr><th>Item</th><th>Quantidade</th><th>Preço cotado</th><th>Total</th></tr></thead><tbody><tr v-for="i in record.order_items" :key="i.id"><td>{{i.name}}</td><td>{{i.quantity}}</td><td>{{money(i.unit_price)}}</td><td>{{money(i.line_total)}}</td></tr></tbody></table></div><h3>Total cotado: {{money(record.total)}}</h3><a v-if="receipt?.whatsapp_url" :href="receipt.whatsapp_url" target="_blank" rel="noopener" class="button outline small">Abrir WhatsApp ↗</a><p class="muted">O pedido não comprova pagamento nem reserva stock.</p><form v-if="transitions?.length" @submit.prevent="transition.post('/admin/pedidos/'+record.id+'/estado')"><div class="form-grid"><div class="field"><label for="new-status">Novo estado</label><select id="new-status" v-model="transition.status" required><option value="">Selecionar…</option><option v-for="s in transitions" :key="s" :value="s">{{states[s]}}</option></select></div><div class="field"><label for="status-reason">Motivo</label><input id="status-reason" v-model="transition.reason" :required="transition.status==='cancelled'"></div></div><button class="button" :disabled="transition.processing">Atualizar estado</button></form><h3>Histórico</h3><ol class="timeline"><li v-for="h in record.order_status_histories" :key="h.id"><strong>{{states[h.to_status]}}</strong> · {{new Date(h.created_at).toLocaleString('pt-AO')}}<p>{{h.reason}}</p></li></ol></template>
<template v-else><h2>{{record.name}}</h2><p>{{record.email}} · {{record.phone}} · {{record.company}}</p><p class="body-copy">{{record.message}}</p></template></section><form v-if="['pedidos','contactos'].includes(kind)&&capabilities?.update" class="panel admin-form" @submit.prevent="details.transform(d=>({...d,assigned_to:d.assigned_to||null})).patch('/admin/'+kind+'/'+record.id)"><h2>Seguimento</h2><div class="form-grid"><div class="field"><label for="assignee">Responsável</label><select id="assignee" v-model="details.assigned_to"><option value="">Sem responsável</option><option v-for="u in assignees" :key="u.id" :value="u.id">{{u.name}}</option></select></div><div v-if="kind==='contactos'" class="field"><label for="contact-status">Estado</label><select id="contact-status" v-model="details.status"><option value="new">Novo</option><option value="in_progress">Em tratamento</option><option value="closed">Encerrado</option></select></div><div v-else class="field full"><label for="order-notes">Notas internas</label><textarea id="order-notes" v-model="details.notes" maxlength="1000"/></div></div><button class="button" :disabled="details.processing">Guardar seguimento</button></form></template></AdminLayout></template>
